	private static final BigInteger TWO = BigInteger.valueOf(2), FIVE = BigInteger.valueOf(5);

	/**
	 * The numeral of an exact value: an integer numeral, or, where an operand had
	 * a radix point or the value is not an integer, a numeral with one, in
	 * decimal where the denominator divides a power of ten.
	 */
	static Expr numeralOf(ExprInfo info, BigInteger n, BigInteger d, boolean point) {
		if (!point && d.equals(BigInteger.ONE)) return ExprFactory.makeIntLiteralExpr(info, n);
		int twos = 0, fives = 0;
		BigInteger r = d;
		while (r.mod(TWO).signum() == 0) { r = r.divide(TWO); twos++; }
		while (r.mod(FIVE).signum() == 0) { r = r.divide(FIVE); fives++; }
		if (r.equals(BigInteger.ONE)) {
			int k = Math.max(Math.max(twos, fives), 1);
			BigInteger scaled = n.multiply(BigInteger.TEN.pow(k)).divide(d);
			String text = new java.math.BigDecimal(scaled, k).toPlainString();
			return new FloatLiteralExpr(info, text, BigInteger.ZERO, scaled, 10, k);
		}
		if (d.bitLength() > 31) return null;
		return new FloatLiteralExpr(info, n + "/" + d, BigInteger.ZERO, n, d.intValue(), 1);
	}

	/**
